const content={observe:{label:'干潟 − 観察',title:'立ち止まると、\n見えてくる。',description:'潮だまりや砂地をのぞいて、生き物の姿や動きを観察。潮の満ち引きで変わる干潟を、ゆっくり探索します。',tags:['潮だまり','生き物の行動','潮の満ち引き']},collect:{label:'干潟 − 採集',title:'見つけた出会いを、\n持ち帰ろう。',description:'網やスコップを使って、干潟の生き物を探します。場所や道具を選びながら、少しずつ採集の楽しさを広げていきます。',tags:['網','スコップ','生き物探し']},aquarium:{label:'ホーム − 水槽',title:'自分だけの水槽で、\nじっくり眺める。',description:'採集した生き物を水槽へ。水槽やインテリアを整えて、自分だけの空間で生き物を眺める時間を楽しみます。',tags:['水槽づくり','インテリア','生き物のコレクション']}};
const tabs=Array.from(document.querySelectorAll('[role=tab]'));
function activate(tab){const selected=content[tab.dataset.mode];tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===tab));t.tabIndex=t===tab?0:-1});document.getElementById('activity-panel').setAttribute('aria-labelledby',tab.id);document.getElementById('activity-label').textContent=selected.label;const photo={observe:['school.webp','水中の魚の群れを観察するゲーム画面'],collect:['shore.webp','網を持って海辺を探索するゲーム画面'],aquarium:['aquarium.webp','生き物を入れた水槽のゲーム画面']}[tab.dataset.mode];document.getElementById('activity-image').src=photo[0];document.getElementById('activity-image').alt=photo[1];const title=document.getElementById('activity-title');title.replaceChildren();selected.title.split('\n').forEach((line,i)=>{if(i)title.append(document.createElement('br'));title.append(document.createTextNode(line))});document.getElementById('activity-description').textContent=selected.description;document.getElementById('activity-tags').replaceChildren(...selected.tags.map(text=>{const s=document.createElement('span');s.textContent=text;return s}));}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>activate(tab));tab.addEventListener('keydown',event=>{let next=index;if(event.key==='ArrowRight'||event.key==='ArrowDown')next=(index+1)%tabs.length;else if(event.key==='ArrowLeft'||event.key==='ArrowUp')next=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();activate(tabs[next]);tabs[next].focus()})});

const viewer=document.getElementById('image-viewer');document.querySelectorAll('.shot-button').forEach(button=>button.addEventListener('click',()=>{const image=document.getElementById('viewer-image');image.src=button.dataset.image;image.alt=button.querySelector('img').alt;document.getElementById('viewer-caption').textContent=button.dataset.caption+' / 開発中のゲーム画面';viewer.showModal()}));document.getElementById('viewer-close').addEventListener('click',()=>viewer.close());viewer.addEventListener('click',event=>{if(event.target===viewer){const r=viewer.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)viewer.close()}});
